"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[4944],{4944:e=>{e.exports=JSON.parse('{"concept":"Probability Sample Spaces","subject":"mathematics","category":"Combinatorics & Counting","explanation":"A sample space is all possible outcomes of an experiment. For coins: {H, T}. For dice: {1, 2, 3, 4, 5, 6}. For two coins: {HH, HT, TH, TT}. Count systematically using lists, tables, or tree diagrams. This helps solve eleven-plus probability problems involving multiple events.","examples":[{"question":"What\'s the sample space for rolling a die and flipping a coin?","solution":"{1H, 1T, 2H, 2T, 3H, 3T, 4H, 4T, 5H, 5T, 6H, 6T}","explanation":"Combine each die outcome (1-6) with each coin outcome (H,T). Total: 6 \xd7 2 = 12 outcomes."},{"question":"If I draw a counter from a bag with 2 red and 3 blue counters, what\'s the sample space?","solution":"{R1, R2, B1, B2, B3} or simply {Red, Blue}","explanation":"Can list individual counters or just colors. For probability, we often just need {Red, Blue} but know there are 2 reds and 3 blues."},{"question":"Two dice are rolled. How many outcomes give a sum of 7?","solution":"6 outcomes","explanation":"Pairs that sum to 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1). That\'s 6 out of 36 total outcomes."}],"exercises":[{"type":"multiple-choice","question":"A spinner has 4 equal sections (A, B, C, D) and I flip a coin. How many possible outcomes?","options":["6","8","10","16"],"correct":[1],"explanation":"4 spinner outcomes \xd7 2 coin outcomes = 8 total: {AH, AT, BH, BT, CH, CT, DH, DT}"},{"type":"multiple-choice","question":"Three coins are flipped. What\'s the probability of getting exactly 2 heads?","options":["1/8","2/8","3/8","4/8"],"correct":[2],"explanation":"Sample space: {HHH, HHT, HTH, HTT, THH, THT, TTH, TTT}. Exactly 2 heads: {HHT, HTH, THH}. So 3/8."},{"type":"open-ended","question":"I have 2 bags: Bag A has numbers 1,2,3 and Bag B has numbers 4,5. I draw one number from each bag. List all possible sums.","sample_answer":"Possible pairs: (1,4)=5, (1,5)=6, (2,4)=6, (2,5)=7, (3,4)=7, (3,5)=8. So possible sums are: 5, 6, 7, 8.","explanation":"Systematically pair each number from Bag A with each from Bag B, then add."}],"tips":["List outcomes systematically - don\'t miss any!","Use tree diagrams for complex multi-stage experiments","Count total outcomes first, then favorable ones","For independent events: multiply the number of outcomes"]}')}}]);